# Let me find all 4-connected components for other colors
def get_4_component(grid, r, c):
    color = grid[r][c]
    visited = set()
    stack = [(r, c)]
    while stack:
        rr, cc = stack.pop()
        if (rr, cc) in visited:
            continue
        visited.add((rr, cc))
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = rr + dr, cc + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == color and (nr,nc) not in visited:
                stack.append((nr, nc))
    return visited

# Find L-shaped components
# An L-shape has a corner cell with both a horizontal and vertical arm

def has_arm(comp, corner, direction):
    """Check if component has an arm from corner in given direction."""
    for pos in comp:
        if pos == corner:
            continue
        dr = pos[0] - corner[0]
        dc = pos[1] - corner[1]
        # Arm means moving only in one cardinal direction from corner
        if direction == 'vertical' and dc == 0 and dr != 0:
            return True
        if direction == 'horizontal' and dr == 0 and dc != 0:
            return True
    return False

